import { TransformNode, SceneLoader } from '@babylonjs/core';
import { applyModelPaint } from '../../../utils/modelPaint.js';

// Player base hull — ORIGINAL mesh (M26 Pershing-inspired), generated by
// scripts/modelgen/player_hull_base.py. Semantic mesh names drive paint:
// wheel_*/track_*/engine_* stay dark automatically, no skip list needed.

const PAINT = { paintColor: [0.12, 0.42, 0.88] };  // cobalt — current player default

export default {
  id: 'player-hull-base',
  name: 'Player Hull',
  category: 'hull',
  stats: {},
  mountEmpty: 'turret',
  nativeTurret: 'player-turret-base',
  ringDiameter: 1.95,   // mirrors ringD in scripts/modelgen/params/
  footprint: { halfW: 1.4, halfD: 2.3 },   // collision box (authored, not measured)

  async build(scene, paintOverride = null) {
    const result = await SceneLoader.ImportMeshAsync('', '/assets/models/tanks/parts/', 'player_hull_base.glb', scene);
    const mountNode = result.transformNodes.find(n => n.name === this.mountEmpty);
    const mount = mountNode ? mountNode.getAbsolutePosition().clone() : null;

    const root = new TransformNode('hull_player_root', scene);
    const meshes = result.meshes.filter(m => m.name !== '__root__');
    for (const m of meshes) m.setParent(root);

    applyModelPaint(meshes, PAINT, scene, paintOverride);
    return { root, meshes, mount, ringCenter: mount };
  },
};
